    #[doc = " Look up a backend's vtable by name. Returns NULL if no backend is\n  registered under `name`. The returned pointer is valid for the\n  program's lifetime."]
    pub fn nros_rmw_cffi_lookup(name: *const core::ffi::c_char) -> *const nros_rmw_vtable_t;
